// TH15 synthetic bullet aliases (type -> modern catalog slot), see
// transcribe/th15/bullet-types.md + touhou-bullets.ecl. Only the types used by
// this card are copied; source stays "th15".
const TH15_BALL2: int = 432;       // source type 5, base radius 4 (Phantom01_at)
const TH15_RING_BALL2: int = 464;  // source type 7, base radius 4 (GirlD01_at)

// TH15 Stage 1 stage wave: MainSub03 (st01.ecl.txt:1004-1014).
// Two GirlD01 (source:497-562), each bracketing a MainSub01b (source:968-982)
// nine-pair Phantom01 sweep (source:1173-1216).
// Source local frame 0 == card frame OPENING_BUFFER: the pattern task waits 120
// frames before spawning, so the source attack starts after the opening buffer.

const TIME_LIMIT: int = 2124;      // 120 opening buffer + 2000-frame schedule/tail estimate
const OPENING_BUFFER: int = 120;

// Phantom01:1183 moveEllipseRel(phase, 0.034906585 rad/frame, r=10, 0, ABS_ANGLE, 0).
// Phase = inherited parent F0 (0.087266 - 20*0.003491 = 0.017446 rad ~= 182 BAM).
// omega 0.034906585 rad/frame = 2deg = 364 BAM/frame. ratio 0 with axis pi/2
// reduces to x = x0 + r*cos(theta), y unchanged (see circular-motion.md).
const PHANTOM_PHASE_BAM: int = 182;
const PHANTOM_OMEGA_BAM: int = 364;

// GirlD01_at:542-543 Lunatic-only EX 0x200000 VELTIME: a=60 running ramp,
// r=4.0 target scalar speed, s=-999999 keeps the current direction.
xformdef LUNATIC_SPEEDUP {
    step_speed(4fx, 60);
}

// Phantom01_at (source:1197-1216); spawned only under the !HL mask at :1184-1186.
async sub phantom_fire() {
    var rank: int = global(GVAR_RANK);
    var shots: int = 1;
    if rank == RANK_LUNATIC { shots = 2; }        // :1208 diffI(1,1,1,2)
    var i: int = 0;
    while i < shots {
        wait(60 + rand(90));                      // :1211 wait(60 + ($RAND % 90))
        var aim: angle = aim_player();            // :1201/:1204 mode0 N=1 -> one aimed angle
        if rank == RANK_LUNATIC {
            var q: int = 0;
            while q < 8 {                         // :1203/:1205 layers=8, speed 3..1
                var u: fx = (q as fx) / 7fx;
                var spd: fx = 3fx + (1fx - 3fx) * u;
                _ = fire(TH15_BALL2, 4, $self_x, $self_y, spd, aim, none, none);
                q = q + 1;
            }
        } else {
            _ = fire(TH15_BALL2, 4, $self_x, $self_y, 3fx, aim, none, none);
        }
        i = i + 1;
    }
}

// Phantom01 (source:1173-1195). The REL ellipse is composed onto the ABS descent
// by hand: x = x0 + 10*cos(theta), y integrated from the 1.0 -> 1.5 quart-in ramp.
async sub phantom(x0: fx, phase_bam: int) {
    set_invuln(65535);
    set_hurtbox(14fx);                 // :1177 setHurtbox(28,28) -> r=14 (circle branch w/2)
    set_hitbox(8fx);                   // :1178 setHitbox(16,16) -> r=8
    if global(GVAR_RANK) >= RANK_HARD { spawn phantom_fire(); }
    // :1179/:1188 flagSet(12)/flagClear(12) suppress source offscreen recycling for the
    // first 60 frames. Target spawns at y=-24 survive entry (run confirms) and are
    // recycled after leaving the play area, matching the post-flagClear behaviour.
    var y: fx = -24fx;
    var t: int = 0;
    loop {
        var spd: fx = 1.5fx;           // :1182 moveVelTime(120, mode3, pi/2, 1.5): quart-in 1->1.5
        if t < 120 {
            var u: fx = (t as fx) / 120fx;
            spd = 1fx + 0.5fx * u * u * u * u;
        }
        var theta: int = phase_bam + PHANTOM_OMEGA_BAM * t;
        var relx: fx = 10fx * cos(theta as angle);  // :1183 ratio=0, axis=pi/2
        move_to(0, x0 + relx, y, EASE_LINEAR);
        y = y + spd;
        t = t + 1;
        wait(1);
    }
}

// MainSub01b (source:968-982): nine mirrored Phantom01 pairs, 30 frames apart.
sub phantom_batch() {
    var k: int = 1;
    while k <= 9 {
        var px: fx = (k * 16) as fx;   // :971/:975 %A starts 0 then += 16 each pass
        _ = spawn_enemy(px, -24fx, 90, 0, 1000, 0, phantom(px, PHANTOM_PHASE_BAM));
        _ = spawn_enemy(0fx - px, -24fx, 90, 0, 1000, 0, phantom(0fx - px, PHANTOM_PHASE_BAM));
        wait(30);                      // :978
        k = k + 1;
    }
}

// GirlD01_at (source:522-562). Shooter slot 0 is task-private (one per GirlD01).
async sub girl_fire() {
    wait(60);                          // :525
    var rank: int = global(GVAR_RANK);
    // :529-537 stack value -> etCount layers 2 (Easy) / 6 (others); :545 diffI waves.
    var layers: int = 6;
    var waves: int = 10;
    var gap: int = 30;
    if rank == RANK_EASY { layers = 2; waves = 2; gap = 120; }
    else if rank == RANK_NORMAL { layers = 6; waves = 3; gap = 120; }
    else if rank == RANK_HARD { layers = 6; waves = 6; gap = 60; }
    else { layers = 6; waves = 10; gap = 30; }

    // :526/:527/:530/:539/:540 etNew, etAim(9), etSprite(7,4), etAngle(0,3deg), etSpeed(1.6,1.6).
    sh_reset(0);
    sh_sprite(0, TH15_RING_BALL2, 4);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 10, 1);
    sh_speed(0, 1.6fx, 0fx);
    if rank == RANK_LUNATIC { sh_xform(0, LUNATIC_SPEEDUP); }

    var i: int = 0;
    while i < waves {
        var aim_bam: int = aim_player() as int;   // mode 9 samples the player angle once per wave
        var q: int = 0;
        while q < layers {
            // mode 9: A + (-1)^q*(R(i)+H), H=(floor(q/2)+1/2)*delta, delta=3deg=546 BAM.
            // Negating the whole ring keeps the same 10-way set at base A -/+ H.
            var h: int = (q / 2) * 546 + 273;
            var off: int = h;
            if q % 2 != 0 { off = 0 - h; }
            sh_angle(0, (aim_bam + off) as angle, 0deg);
            sh_fire(0);
            q = q + 1;
        }
        i = i + 1;
        wait(gap);                     // :549-558
    }
}

// GirlD01 (source:497-520).
async sub girl() {
    set_invuln(65535);
    set_hurtbox(16fx);                 // :506 setHurtbox(32,32) -> r=16
    set_hitbox(12fx);                  // :507 setHitbox(24,24) -> r=12
    move_vel(0, 90deg, 3fx, EASE_LINEAR);       // :508
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN);     // :509 mode1 (quad in) 3 -> 0
    spawn girl_fire();                          // :510 async
    wait(80);                                   // :511
    move_speed(120, 1fx, EASE_QUAD_IN);         // :512 mode1 0 -> 1
    wait(60);                                   // :513
    loop { wait(1); }                           // :515-519 endless wait loop
}

// MainSub03 schedule (source:1004-1014); parent FINAL is the stage origin.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-32fx, -24fx, 1600, 0, 1000, 0, girl());   // :1006
    wait(60);                                                  // :1007
    phantom_batch();                                           // :1008
    wait(80);                                                  // :1009
    _ = spawn_enemy(32fx, -24fx, 1600, 0, 1000, 0, girl());    // :1010
    wait(20);                                                  // :1011
    phantom_batch();                                           // :1012
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
